def compute_partial_refund(item_price, quantity, discount_rate, currency):
    """Calculate the refund amount for a partial refund with discount applied."""
    gross = item_price * quantity
    discount = gross * discount_rate
    net = gross - discount
    # Quantize to the smallest currency unit (e.g., 0.01 for EUR, 1 for JPY)
    quantized_net = net.quantize(currency_smallest_unit(currency), rounding=ROUND_DOWN)
    return quantized_net

