from decimal import Decimal, ROUND_DOWN

def convert_currency(amount, from_currency, to_currency):
    """
    Convert an amount from one currency to another using a fixed rate.

    Args:
        amount (Decimal): The amount to convert.
        from_currency (str): The source currency code.
        to_currency (str): The target currency code.

    Returns:
        Decimal: The converted amount in the target currency.
    """
    # In a real system, this would fetch the current exchange rate.
    # For this example, we use a fixed rate.
    rate = get_fixed_rate(from_currency, to_currency)
    converted = amount * rate
    return converted.quantize(Decimal('1.00'), rounding=ROUND_DOWN)

def get_fixed_rate(from_currency, to_currency):
    # This is a simplified example; in practice, this would be dynamic.
    if from_currency == 'JPY' and to_currency == 'USD':
        return Decimal('0.0090')
    elif from_currency == 'USD' and to_currency == 'JPY':
        return Decimal('111.11')
    elif from_currency == 'EUR' and to_currency == 'USD':
        return Decimal('1.0871')
    elif from_currency == 'USD' and to_currency == 'EUR':
        return Decimal('0.9200')
    else:
        return Decimal('1.00')  # Assume 1:1 for other pairs for simplicity

